INSERT INTO posts (title, slug, category, category_id, excerpt, content, image, seo_title, seo_description, seo_keywords, seo_image, hide_placeholder_image, show_on_home, priority, author_id, author_name, author_role, views_count, published_at, is_published)
SELECT 'Добро пожаловать в FIREBALL CMS', 'welcome-to-fireball-cms', category.name, category.id,
'Познакомьтесь с публикациями, страницами и личным кабинетом на примере готового демонстрационного сайта.',
REPLACE('<p>Этот сайт — отправная точка для вашего проекта. Здесь уже есть несколько категорий, публикации, информационные страницы и один черновик. Откройте материалы в админ-панели, посмотрите, как они устроены, и замените их своими.</p>
<div class="alert alert-info" role="alert"><strong>Это демонстрационный контент.</strong> Иллюстрации и тексты служат примерами. Перед запуском удалите ненужные материалы и настройте сайт под свой проект.</div>
<h2>Что попробовать первым</h2><ol><li>Откройте раздел «Записи» и отредактируйте заголовок, обложку и описание этой публикации.</li><li>Перейдите в «Страницы»: поменяйте текст и расположение ссылок в меню.</li><li>Загрузите собственные файлы через файловый менеджер и выберите их в редакторе.</li><li>Откройте профиль, проверьте настройки аккаунта и добавьте понравившуюся запись в избранное.</li></ol>
<h2>Что входит в демо</h2><p>В руководствах показаны работа с блочным редактором, галерея изображений, таблица, FAQ и чек-лист. Раздел «Идеи для сайта» поможет выбрать структуру проекта. Счётчики просмотров начинаются с нуля: демо не добавляет вымышленных посетителей.</p>
<p><a href="{{base_path}}/features">Посмотреть возможности</a> · <a href="{{base_path}}/demo-launch-guide">Памятка перед запуском</a></p>', '{{base_path}}', :base_path),
'assets/default/images/demo/workspace.svg', 'Добро пожаловать в FIREBALL CMS', 'Готовые примеры публикаций и страниц для знакомства с FIREBALL CMS.', 'fireball cms, демо, возможности', 'assets/default/images/demo/workspace.svg', 0, 1, 100, author.id, COALESCE(NULLIF(TRIM(author.name), ''), 'Creator'), 'creator', 0, :now, 1
FROM post_categories category JOIN users author ON author.id = :creator_id AND author.role = 'creator' WHERE category.slug = 'demo'
ON DUPLICATE KEY UPDATE title = VALUES(title), category = VALUES(category), category_id = VALUES(category_id), excerpt = VALUES(excerpt), content = VALUES(content), image = VALUES(image), seo_title = VALUES(seo_title), seo_description = VALUES(seo_description), seo_keywords = VALUES(seo_keywords), seo_image = VALUES(seo_image), hide_placeholder_image = VALUES(hide_placeholder_image), show_on_home = VALUES(show_on_home), priority = VALUES(priority), author_id = VALUES(author_id), author_name = VALUES(author_name), author_role = VALUES(author_role), published_at = VALUES(published_at), is_published = VALUES(is_published);

INSERT INTO posts (title, slug, category, category_id, excerpt, content, image, seo_title, seo_description, seo_keywords, seo_image, hide_placeholder_image, show_on_home, priority, author_id, author_name, author_role, views_count, published_at, is_published)
SELECT 'Первая публикация: от идеи до готовой записи', 'first-publication', category.name, category.id,
'Заголовок, краткое описание, категория и обложка: простой порядок подготовки материала к публикации.',
REPLACE('<p>Хорошая запись отвечает на один понятный вопрос читателя. Начните с идеи, а оформление добавляйте по мере необходимости — так проще сделать материал полезным и аккуратным.</p>
<h2>Подготовьте основу</h2><ol><li><strong>Заголовок.</strong> Коротко сформулируйте тему, без общих обещаний.</li><li><strong>Описание.</strong> Расскажите в одном-двух предложениях, что читатель узнает.</li><li><strong>Категория.</strong> Выберите раздел, в котором посетитель ожидает найти этот материал.</li><li><strong>Обложка.</strong> Используйте изображение с правом публикации и проверьте его кадрирование.</li></ol>
<h2>Соберите содержание</h2><p>Разделите длинный текст подзаголовками. Для шагов используйте нумерованный список, для сравнения — таблицу. Изображению добавьте осмысленный альтернативный текст, а ссылке — понятное название.</p>
<blockquote>Одна публикация — одна основная мысль. Всё остальное помогает её объяснить.</blockquote>
<h2>Проверьте перед публикацией</h2><ul><li>Заголовок и описание хорошо смотрятся в списке записей.</li><li>Ссылки ведут на существующие страницы.</li><li>Изображения не растягиваются на телефоне.</li><li>Дата публикации и состояние записи выбраны правильно.</li></ul><p>Если материал ещё не готов, оставьте его черновиком. Пример черновика уже есть в админ-панели.</p>', '{{base_path}}', :base_path),
'assets/default/images/demo/content.svg', 'Как подготовить первую публикацию', 'Практический порядок создания записи: текст, обложка, категория и проверка перед публикацией.', 'публикации, контент, редактор', 'assets/default/images/demo/content.svg', 0, 1, 90, author.id, COALESCE(NULLIF(TRIM(author.name), ''), 'Creator'), 'creator', 0, DATE_SUB(:now, INTERVAL 1 DAY), 1
FROM post_categories category JOIN users author ON author.id = :creator_id AND author.role = 'creator' WHERE category.slug = 'guides'
ON DUPLICATE KEY UPDATE title = VALUES(title), category = VALUES(category), category_id = VALUES(category_id), excerpt = VALUES(excerpt), content = VALUES(content), image = VALUES(image), seo_title = VALUES(seo_title), seo_description = VALUES(seo_description), seo_keywords = VALUES(seo_keywords), seo_image = VALUES(seo_image), hide_placeholder_image = VALUES(hide_placeholder_image), show_on_home = VALUES(show_on_home), priority = VALUES(priority), author_id = VALUES(author_id), author_name = VALUES(author_name), author_role = VALUES(author_role), published_at = VALUES(published_at), is_published = VALUES(is_published);

