SELECT 'Блочный редактор: галерея, таблица и ответы на вопросы', 'block-editor-examples', category.name, category.id,
'Посмотрите готовые примеры блоков и откройте запись в редакторе, чтобы настроить их под свой материал.',
REPLACE('{"version":2,"blocks":[
{"id":"demo-blocks-intro","type":"text","data":{"html":"<p>Блоки помогают собрать материал из понятных частей. Этот пример показывает изображения, таблицу и вопросы с раскрывающимися ответами. Оформление использует текущий шаблон CMS.</p>"}},
{"id":"demo-gallery-heading","type":"heading","data":{"level":"h2","html":"Галерея изображений"}},
{"id":"demo-gallery-intro","type":"text","data":{"html":"<p>Нажмите на иллюстрацию: изображения этой галереи можно переключать в общем окне просмотра. Замените их собственными файлами из файлового менеджера.</p>"}},
{"id":"demo-gallery","type":"gallery","data":{"items":[{"src":"{{base_path}}/assets/default/images/demo/workspace.svg","alt":"Демонстрационная иллюстрация рабочего пространства","caption":"Рабочее пространство проекта"},{"src":"{{base_path}}/assets/default/images/demo/content.svg","alt":"Демонстрационная иллюстрация структуры публикации","caption":"Материалы и публикации"},{"src":"{{base_path}}/assets/default/images/demo/community.svg","alt":"Демонстрационная иллюстрация общения с аудиторией","caption":"Аккаунт и сообщество"}]}},
{"id":"demo-table-heading","type":"heading","data":{"level":"h2","html":"Таблица для сравнения"}},
{"id":"demo-table","type":"table","data":{"header":true,"bordered":true,"responsive":true,"rows":[["Блок","Когда использовать","Что проверить"],["Галерея","Несколько связанных изображений","Порядок, подписи и альтернативный текст"],["Таблица","Сравнение характеристик или этапов","Читаемость на небольшом экране"],["FAQ","Короткие ответы на повторяющиеся вопросы","Понятные заголовки вопросов"]]}},
{"id":"demo-faq-heading","type":"heading","data":{"level":"h2","html":"Частые вопросы"}},
{"id":"demo-blocks-faq","type":"faq","data":{"items":[{"question":"Нужно ли знать HTML?","answer":"<p>Для обычного текста, списков, изображений и других готовых блоков HTML не требуется. Выбирайте блок и меняйте его содержимое в редакторе.</p>"},{"question":"Как изменить порядок изображений?","answer":"<p>Откройте настройки галереи, переставьте изображения и сохраните запись. Затем проверьте порядок на публичной странице.</p>"},{"question":"Можно ли взять уже загруженный файл?","answer":"<p>Да. Используйте выбор из файлового менеджера там, где он доступен в настройках блока, вместо повторной загрузки с компьютера.</p>"}]}}
]}', '{{base_path}}', :base_path),
'assets/default/images/demo/content.svg', 'Примеры блоков FIREBALL CMS', 'Галерея изображений, адаптивная таблица и FAQ в одной демонстрационной публикации.', 'блочный редактор, галерея, таблица, faq', 'assets/default/images/demo/content.svg', 0, 1, 80, author.id, COALESCE(NULLIF(TRIM(author.name), ''), 'Creator'), 'creator', 0, DATE_SUB(:now, INTERVAL 2 DAY), 1
FROM post_categories category JOIN users author ON author.id = :creator_id AND author.role = 'creator' WHERE category.slug = 'guides'
