INSERT INTO posts (title, slug, category, category_id, excerpt, content, image, seo_title, seo_description, seo_keywords, seo_image, hide_placeholder_image, show_on_home, priority, author_id, author_name, author_role, views_count, published_at, is_published)
SELECT 'Личный кабинет: профиль, избранное и безопасность', 'account-and-security', category.name, category.id,
'Разделы аккаунта помогают настроить профиль, сохранить полезные записи и проверить устройства и сессии.',
REPLACE('<p>Личный кабинет объединяет настройки аккаунта и персональные разделы сайта. Их состав зависит от установленных плагинов и доступных возможностей.</p>
<h2>Профиль и аватар</h2><p>Укажите имя, которое увидят другие пользователи, и загрузите аватар. После сохранения проверьте, как изображение выглядит в навигации и в карточке профиля.</p>
<h2>Избранное</h2><p>Нажмите на сердечко у записи, чтобы сохранить её. Добавленные материалы доступны в разделе «Избранное»; повторное нажатие убирает запись из списка.</p>
<h2>Устройства и сессии</h2><p>Периодически проверяйте список входов. Если обнаружили незнакомую сессию, завершите её и смените пароль. Не используйте один пароль для разных сервисов.</p>
<h2>Безопасность аккаунта</h2><ul><li>Выберите длинный уникальный пароль.</li><li>Если двухфакторная аутентификация доступна, включите её в настройках безопасности.</li><li>Проверьте актуальность почты для восстановления доступа.</li><li>На чужом устройстве обязательно выйдите из аккаунта.</li></ul><p><a href="{{base_path}}/profile">Открыть личный кабинет</a></p>', '{{base_path}}', :base_path),
'assets/default/images/demo/community.svg', 'Личный кабинет FIREBALL CMS', 'Профиль, избранные записи, устройства и основные настройки безопасности аккаунта.', 'профиль, избранное, устройства, безопасность', 'assets/default/images/demo/community.svg', 0, 1, 70, author.id, COALESCE(NULLIF(TRIM(author.name), ''), 'Creator'), 'creator', 0, DATE_SUB(:now, INTERVAL 3 DAY), 1
FROM post_categories category JOIN users author ON author.id = :creator_id AND author.role = 'creator' WHERE category.slug = 'guides'
ON DUPLICATE KEY UPDATE title = VALUES(title), category = VALUES(category), category_id = VALUES(category_id), excerpt = VALUES(excerpt), content = VALUES(content), image = VALUES(image), seo_title = VALUES(seo_title), seo_description = VALUES(seo_description), seo_keywords = VALUES(seo_keywords), seo_image = VALUES(seo_image), hide_placeholder_image = VALUES(hide_placeholder_image), show_on_home = VALUES(show_on_home), priority = VALUES(priority), author_id = VALUES(author_id), author_name = VALUES(author_name), author_role = VALUES(author_role), published_at = VALUES(published_at), is_published = VALUES(is_published);

INSERT INTO posts (title, slug, category, category_id, excerpt, content, image, seo_title, seo_description, seo_keywords, seo_image, hide_placeholder_image, show_on_home, priority, author_id, author_name, author_role, views_count, published_at, is_published)
SELECT 'PWA и уведомления: что проверить на своём устройстве', 'pwa-and-notifications', category.name, category.id,
'Как проверить установку сайта, разрешение на уведомления и привязку устройства без вымышленных тестовых пушей.',
REPLACE('<p>Если владелец сайта настроил PWA, сайт можно открывать как установленное приложение. Наличие установки и возможность Push-уведомлений зависят от браузера, устройства и настроек сайта.</p>
<h2>Проверка по шагам</h2><ol><li>Откройте сайт и найдите доступную в браузере команду установки или добавления на главный экран.</li><li>Запустите установленное приложение и войдите в аккаунт.</li><li>Откройте настройки уведомлений в личном кабинете.</li><li>Разрешите уведомления, если хотите их получать, и дождитесь результата проверки.</li><li>При изменении устройства или разрешений повторно проверьте статус.</li></ol>
<h2>Если уведомления не приходят</h2><ul><li>Проверьте разрешения браузера и системы.</li><li>Проверьте, включены ли уведомления для аккаунта.</li><li>Убедитесь, что устройство ещё привязано на сайте.</li><li>Попросите администратора проверить технический журнал отправок.</li></ul>
<div class="alert alert-secondary" role="alert">Технический статус отправки не равен подтверждению прочтения пользователем. Демо-набор не регистрирует устройства и не отправляет уведомления.</div>', '{{base_path}}', :base_path),
'assets/default/images/demo/community.svg', 'PWA и уведомления на вашем устройстве', 'Проверка установки PWA, разрешений уведомлений и состояния привязанного устройства.', 'pwa, уведомления, устройства', 'assets/default/images/demo/community.svg', 0, 1, 60, author.id, COALESCE(NULLIF(TRIM(author.name), ''), 'Creator'), 'creator', 0, DATE_SUB(:now, INTERVAL 4 DAY), 1
FROM post_categories category JOIN users author ON author.id = :creator_id AND author.role = 'creator' WHERE category.slug = 'guides'
ON DUPLICATE KEY UPDATE title = VALUES(title), category = VALUES(category), category_id = VALUES(category_id), excerpt = VALUES(excerpt), content = VALUES(content), image = VALUES(image), seo_title = VALUES(seo_title), seo_description = VALUES(seo_description), seo_keywords = VALUES(seo_keywords), seo_image = VALUES(seo_image), hide_placeholder_image = VALUES(hide_placeholder_image), show_on_home = VALUES(show_on_home), priority = VALUES(priority), author_id = VALUES(author_id), author_name = VALUES(author_name), author_role = VALUES(author_role), published_at = VALUES(published_at), is_published = VALUES(is_published);

