SELECT 'Чек-лист перед запуском сайта', 'site-launch-checklist', category.name, category.id,
'Настройки, контент, доступы и проверка на телефоне — список того, что стоит пройти перед открытием сайта.',
REPLACE('{"version":2,"blocks":[
{"id":"demo-checklist-intro","type":"text","data":{"html":"<p>Перед запуском пройдите сайт глазами посетителя. Этот список — пример блока чек-листа: в редакторе его можно дополнить задачами своего проекта.</p>"}},
{"id":"demo-checklist","type":"checklist","data":{"items":[{"text":"Заменить название, описание и логотип сайта.","checked":false},{"text":"Удалить или переработать демонстрационные материалы.","checked":false},{"text":"Проверить обложки, подписи и ссылки в публикациях.","checked":false},{"text":"Настроить страницы и ссылки в верхнем и нижнем меню.","checked":false},{"text":"Проверить вход, восстановление доступа и отправку писем после настройки почты.","checked":false},{"text":"Проверить роли команды и включённые плагины.","checked":false},{"text":"Создать резервную копию и проверить порядок восстановления.","checked":false},{"text":"Открыть сайт на телефоне и компьютере, проверить поиск и галерею.","checked":false}]}},
{"id":"demo-checklist-heading","type":"heading","data":{"level":"h2","html":"Не забудьте про демонстрационные данные"}},
{"id":"demo-checklist-note","type":"text","data":{"html":"<p>Демо — учебный набор, а не готовые сведения о вашей компании. Не публикуйте примеры как реальные обещания, статистику или условия услуг. Наполните страницы актуальными данными своего проекта.</p>"}},
{"id":"demo-checklist-link","type":"text","data":{"html":"<p><a href={{base_path}}/demo-launch-guide>Открыть подробную памятку</a></p>"}}
]}', '{{base_path}}', :base_path),
'assets/default/images/demo/workspace.svg', 'Чек-лист запуска сайта на FIREBALL CMS', 'Проверьте контент, настройки, доступы, резервную копию и отображение сайта перед запуском.', 'запуск сайта, чек-лист, настройки', 'assets/default/images/demo/workspace.svg', 0, 1, 50, author.id, COALESCE(NULLIF(TRIM(author.name), ''), 'Creator'), 'creator', 0, DATE_SUB(:now, INTERVAL 5 DAY), 1
